import {api,type ChangePreview,type ChangeResult,type Dimension,type Domain,type Metric,type MetricFilter,type ModelSummary,type ObjectSource,type QueryResponse,type Relationship,type SearchResult,type SemanticObject,type ValidationResponse} from './api';

type IconName='catalog'|'metrics'|'search'|'query'|'diagram'|'changes'|'connect'|'check'|'branch'|'table'|'code'|'copy'|'arrow'|'warning'|'close';
function Icon({name,size=18}:{name:IconName;size?:number}){const paths:Record<IconName,ReactNode>={catalog:<><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,metrics:<><path d="M4 19V9M10 19V5M16 19v-7M22 19H2"/></>,search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,query:<><path d="m5 7 4 4-4 4M12 17h7"/><rect x="2" y="3" width="20" height="18" rx="2"/></>,diagram:<><rect x="2" y="3" width="7" height="6" rx="1"/><rect x="15" y="15" width="7" height="6" rx="1"/><path d="M9 6h4a5 5 0 0 1 5 5v4"/></>,changes:<><path d="M7 3v12a4 4 0 0 0 4 4h6M7 7l-3-3m3 3 3-3"/><circle cx="18" cy="19" r="2"/></>,connect:<><path d="M8 12h8M12 8v8"/><path d="M6 4h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z"/></>,check:<path d="m5 12 4 4L19 6"/>,branch:<><circle cx="6" cy="5" r="2"/><circle cx="18" cy="7" r="2"/><circle cx="6" cy="19" r="2"/><path d="M6 7v10M8 9c5 0 5-2 8-2"/></>,table:<><rect x="3" y="4" width="18" height="16" rx="1"/><path d="M3 9h18M9 9v11"/></>,code:<path d="m8 9-4 3 4 3m8-6 4 3-4 3m-3-9-2 12"/>,copy:<><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></>,arrow:<path d="m9 18 6-6-6-6"/>,warning:<><path d="M12 3 2.8 20h18.4L12 3Z"/><path d="M12 9v4m0 3h.01"/></>,close:<path d="m6 6 12 12M18 6 6 18"/>};return <svg className="icon-svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>}

const navExplore=[['/','Catalog','catalog'],['/metrics','Metrics','metrics'],['/search','Search','search'],['/query','Query','query'],['/diagram','ER Diagram','diagram']] as const;
const navGovern=[['/changes','Changes','changes'],['/connect','Connect','connect']] as const;

export default function App(){return <Shell/>}
function Shell(){const location=useLocation(),navigate=useNavigate();const[search,setSearch]=useState('');const crumb=breadcrumb(location.pathname);const submit=(e:FormEvent)=>{e.preventDefault();if(search.trim())navigate('/search?q='+encodeURIComponent(search.trim()))};return <div className="app-shell"><aside className="rail"><Link to="/" className="brand"><span className="brand-mark">W</span><span className="brand-copy"><strong>Witness</strong><small>Semantic Layer</small></span></Link><NavGroup label="Explore" items={navExplore}/><NavGroup label="Govern" items={navGovern}/><div className="rail-status"><span className="status-dot success"/><span><strong>Model active</strong><small>Serving main</small></span></div></aside><div className="workspace"><header className="topbar"><div className="breadcrumb"><span>Witness</span><b>/</b><strong>{crumb}</strong></div><form className="global-search" onSubmit={submit}><Icon name="search" size={16}/><input aria-label="Global search" placeholder="Search objects and metrics" value={search} onChange={e=>setSearch(e.target.value)}/><kbd>⌘ K</kbd></form><div className="top-actions"><span className="state-pill"><span className="status-dot success"/>main · read-only</span><span className="avatar" aria-label="Current user">AK</span></div></header><main className="main-content"><Routes><Route path="/" element={<Catalog/>}/><Route path="/metrics/new" element={<MetricObjectPicker/>}/><Route path="/metrics" element={<MetricsRegistry/>}/><Route path="/objects/:id/edit" element={<ObjectEditor/>}/><Route path="/objects/:id" element={<ObjectDetail/>}/><Route path="/objects/:id/metrics/:metric" element={<MetricEditor/>}/><Route path="/query" element={<QueryWorkspace/>}/><Route path="/changes" element={<ChangeWizard/>}/><Route path="/connect" element={<ConnectPage/>}/><Route path="/search" element={<SearchPage/>}/><Route path="/diagram" element={<Diagram/>}/><Route path="/editor" element={<Navigate to="/changes" replace/>}/><Route path="*" element={<NotFound/>}/></Routes></main></div></div>}
function NavGroup({label,items}:{label:string;items:readonly(readonly[string,string,IconName])[]}){return <section className="nav-group"><div className="nav-label">{label}</div><nav>{items.map(([to,text,icon])=><NavLink key={to} to={to} end={to==='/' }><Icon name={icon}/><span>{text}</span></NavLink>)}</nav></section>}
function breadcrumb(path:string){if(path==='/')return'Catalog';const parts=path.split('/').filter(Boolean);return parts.map(p=>p.replaceAll('_',' ')).map(p=>p.charAt(0).toUpperCase()+p.slice(1)).join(' / ')}

function PageHeader({eyebrow,title,description,actions}:{eyebrow:string;title:string;description?:string;actions?:ReactNode}){return <header className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div>{actions&&<div className="header-actions">{actions}</div>}</header>}
function Loading({label='Loading model'}:{label?:string}){return <div className="state-card" role="status"><span className="spinner"/><strong>{label}</strong><small>Please wait a moment</small></div>}
function Empty({title,body,action}:{title:string;body:string;action?:ReactNode}){return <div className="empty"><span className="empty-icon"><Icon name="search"/></span><h3>{title}</h3><p>{body}</p>{action}</div>}
function ErrorState({message,hint}:{message:string;hint?:string}){return <div className="alert error" role="alert"><Icon name="warning"/><div><strong>{message}</strong>{hint&&<p>{hint}</p>}</div></div>}
function Tags({items}:{items:string[]}){return <span className="tags">{items.map(tag=><span key={tag}>{tag}</span>)}</span>}
function Verified({value=true}:{value?:boolean}){return value?<span className="verified"><Icon name="check" size={12}/>Verified</span>:<span className="warning-badge"><Icon name="warning" size={12}/>Unverified</span>}
function isVerified(metadata:{description?:string;owner?:string}){return Boolean(metadata.description?.trim()&&metadata.owner?.trim())}
function objectId(object:SemanticObject){return `${object.metadata.domain}.${object.metadata.name}`}
function metricId(metric:Metric){return `${metric.metadata.domain}.${metric.metadata.name}`}
function baseObjectId(metric:Metric){return metric.spec.baseObject.includes('.')?metric.spec.baseObject:`${metric.metadata.domain}.${metric.spec.baseObject}`}
function metricBelongsTo(metric:Metric,object:SemanticObject){return baseObjectId(metric)===objectId(object)}

function Catalog(){const[model,setModel]=useState<ModelSummary>(),[objects,setObjects]=useState<SemanticObject[]>([]),[metrics,setMetrics]=useState<Metric[]>([]),[q,setQ]=useState(''),[domain,setDomain]=useState('all'),[error,setError]=useState('');useEffect(()=>{let active=true,loaded=false;const load=()=>Promise.all([api<ModelSummary>('/model'),api<SemanticObject[]>('/objects'),api<Metric[]>('/metrics')]).then(([m,o,x])=>{if(!active)return;setModel(m);setObjects(o);setMetrics(x);setError('');loaded=true}).catch(e=>{if(active&&!loaded)setError(e.message)});load();const timer=window.setInterval(load,5000);return()=>{active=false;window.clearInterval(timer)}},[]);const visible=useMemo(()=>objects.filter(o=>(domain==='all'||o.metadata.domain===domain)&&JSON.stringify(o.metadata).toLowerCase().includes(q.toLowerCase())),[objects,q,domain]);if(error)return <ErrorState message={error}/>;if(!model)return <Loading/>;const verified=objects.filter(o=>isVerified(o.metadata)).length+metrics.filter(m=>isVerified(m.metadata)).length;return <><PageHeader eyebrow="Semantic model" title="Semantic model" description={`Resolved from main at ${model.revision?.slice(0,8)||'current revision'}`} actions={<Link className="button primary" to="/objects/new/edit">Create object</Link>}/><section className="stats-grid"><Stat label="Domains" value={model.domains.length} detail="PostgreSQL schemas"/><Stat label="Objects" value={model.objectCount} detail="Virtual tables"/><Stat label="Metrics" value={model.metricCount} detail="Governed measures"/><Stat label="Verified" value={verified} detail="Objects and metrics"/></section><section className="filterbar"><div className="search-field"><Icon name="search" size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search objects, owners or tags"/></div><select aria-label="Filter by domain" value={domain} onChange={e=>setDomain(e.target.value)}><option value="all">All domains</option>{model.domains.map(d=><option key={d.key} value={d.key}>{d.label}</option>)}</select><span className="result-count">{visible.length} objects</span></section>{visible.length===0?<Empty title="No matching objects" body="Try another search or clear the domain filter." action={<button className="button subtle" onClick={()=>{setQ('');setDomain('all')}}>Clear filters</button>}/>:model.domains.filter(d=>domain==='all'||d.key===domain).map(d=><DomainSection key={d.key} domain={d} objects={visible.filter(o=>o.metadata.domain===d.key)} metrics={metrics}/>)}</>}
function Stat({label,value,detail}:{label:string;value:number;detail:string}){return <div className="stat"><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>}
function DomainSection({domain,objects,metrics}:{domain:Domain;objects:SemanticObject[];metrics:Metric[]}){if(!objects.length)return null;return <section className="domain-section"><div className="section-heading"><div><span className="domain-chip">{domain.key}</span><h2>{domain.label}</h2></div><p>schema · {domain.objectCount} objects · {domain.metricCount} metrics</p></div><div className="object-grid">{objects.map(object=>{const count=metrics.filter(m=>metricBelongsTo(m,object)).length,source=object.spec.source;const physical=source.select?'derived SELECT':source.catalog&&source.schema&&source.table?`${source.catalog}.${source.schema}.${source.table}`:'hidden by policy';return <Link className="object-card" to={'/objects/'+objectId(object)} key={objectId(object)}><div className="object-card-top"><h3>{object.metadata.name}</h3><Verified value={isVerified(object.metadata)}/></div><p>{object.metadata.description||'No description yet'}</p><div className="card-meta"><code>{object.spec.dimensions.length} dims · {count} metrics</code></div><footer><span>← {physical}</span><Icon name="arrow" size={15}/></footer></Link>})}</div></section>}

function MetricsRegistry(){const[metrics,setMetrics]=useState<Metric[]>([]),[model,setModel]=useState<ModelSummary>(),[q,setQ]=useState('');useEffect(()=>{Promise.all([api<Metric[]>('/metrics'),api<ModelSummary>('/model')]).then(([m,s])=>{setMetrics(m);setModel(s)})},[]);if(!model)return <Loading label="Loading metrics"/>;const visible=metrics.filter(m=>JSON.stringify(m).toLowerCase().includes(q.toLowerCase()));return <><PageHeader eyebrow="Metric registry" title="Governed business measures" description="Metrics appear as aggregate columns on their base objects." actions={<Link className="button primary" to="/metrics/new">Create metric</Link>}/><section className="filterbar"><div className="search-field"><Icon name="search" size={16}/><input placeholder="Search metrics, owners or objects" value={q} onChange={e=>setQ(e.target.value)}/></div><span className="result-count">{visible.length} metrics</span></section>{model.domains.map(domain=>{const items=visible.filter(m=>m.metadata.domain===domain.key);if(!items.length)return null;return <section className="domain-section" key={domain.key}><div className="section-heading"><div><span className="domain-chip">{domain.key}</span><h2>{domain.label}</h2></div><p>{items.length} measures</p></div><div className="table-panel"><table><thead><tr><th scope="col">Metric</th><th scope="col">Base object</th><th scope="col">Definition</th><th scope="col">Result type</th><th scope="col">Owner</th><th scope="col">Status</th></tr></thead><tbody>{items.map(metric=><tr key={metricId(metric)}><td><Link className="table-link" to={`/objects/${baseObjectId(metric)}/metrics/${metricId(metric)}`}><strong>{metric.metadata.label||metric.metadata.name}</strong><code>{metric.metadata.name}</code></Link></td><td><Link to={'/objects/'+baseObjectId(metric)}><code>{baseObjectId(metric)}</code></Link></td><td><code>{metric.spec.aggregation}({metric.spec.expression})</code></td><td><span className="type-pill">{metric.spec.resultType}</span></td><td>{metric.metadata.owner}</td><td><Verified value={isVerified(metric.metadata)}/></td></tr>)}</tbody></table></div></section>})}</>}
function MetricObjectPicker(){
  const navigate=useNavigate();
  const[objects,setObjects]=useState<SemanticObject[]>([]),[selected,setSelected]=useState(''),[loading,setLoading]=useState(true),[error,setError]=useState('');
  useEffect(()=>{api<SemanticObject[]>('/objects').then(setObjects).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[]);
  if(loading)return <Loading label="Loading semantic objects"/>;
  if(error)return <ErrorState message={error}/>;
  const object=objects.find(candidate=>objectId(candidate)===selected);
  const domains=[...new Set(objects.map(candidate=>candidate.metadata.domain))];
  return <><PageHeader eyebrow="Create metric" title="Choose a base object" description="A metric belongs to one existing semantic object and is exposed as a governed aggregate column on it."/><section className="panel metric-object-picker"><PanelTitle title="Metric placement" meta={<span>{objects.length} objects available</span>}/>{objects.length===0?<Empty title="No semantic objects" body="Create an object before defining its metrics." action={<Link className="button primary" to="/objects/new/edit">Create object</Link>}/>:<><label>Base object<select aria-label="Base object" value={selected} onChange={event=>setSelected(event.target.value)}><option value="">Select an existing object</option>{domains.map(domain=><optgroup key={domain} label={domain}>{objects.filter(candidate=>candidate.metadata.domain===domain).map(candidate=><option key={objectId(candidate)} value={objectId(candidate)}>{candidate.metadata.label||candidate.metadata.name} · {candidate.metadata.name}</option>)}</optgroup>)}</select></label>{object?<div className="selected-object-preview"><div><span className="domain-chip">{object.metadata.domain}</span><strong>{object.metadata.label||object.metadata.name}</strong><code>{object.metadata.domain}.{object.metadata.name}</code></div><p>{object.metadata.description||'No description yet'}</p><small>{object.spec.dimensions.length} dimensions available in metric expressions and filters</small></div>:<div className="callout info"><Icon name="table"/><p>Select the semantic object whose row grain and dimensions this metric should use.</p></div>}<div className="form-actions"><Link className="button subtle" to="/metrics">Cancel</Link><button className="button primary" disabled={!selected} onClick={()=>navigate('/objects/'+selected+'/metrics/new')}>Continue to metric definition</button></div></>}</section></>
}

const objectTabs=['overview','dimensions','metrics','relationships','lineage','yaml'];
function ObjectDetail(){const{id}=useParams();const[params,setParams]=useSearchParams();const tab=params.get('tab')||'overview';const[object,setObject]=useState<SemanticObject>(),[metrics,setMetrics]=useState<Metric[]>([]),[source,setSource]=useState<ObjectSource>(),[error,setError]=useState('');useEffect(()=>{Promise.all([api<SemanticObject>('/objects/'+id),api<Metric[]>('/metrics?object='+id),api<ObjectSource>('/objects/'+id+'/source')]).then(([o,m,s])=>{setObject(o);setMetrics(m);setSource(s)}).catch(e=>setError(e.message))},[id]);if(error)return <ErrorState message={error}/>;if(!object||!source)return <Loading label="Loading object definition"/>;const qualified=objectId(object);return <><PageHeader eyebrow={`Object · ${object.metadata.domain}`} title={object.metadata.label||object.metadata.name} description={object.metadata.description} actions={<><Link className="button subtle" to={`/query?object=${qualified}`}>Query object</Link><Link className="button primary" to={`/objects/${qualified}/edit`}>Edit object</Link></>}/><div className="identity-row"><code>{qualified}</code><Verified value={isVerified(object.metadata)}/><Tags items={object.metadata.tags}/></div><nav className="tabs" aria-label="Object sections">{objectTabs.map(name=><button key={name} className={tab===name?'active':''} onClick={()=>setParams({tab:name})}>{name}</button>)}</nav><section className="tab-content">{tab==='overview'&&<ObjectOverview object={object} source={source}/>} {tab==='dimensions'&&<DimensionsTable object={object}/>} {tab==='metrics'&&<ObjectMetrics object={object} metrics={metrics}/>} {tab==='relationships'&&<Relationships object={object}/>} {tab==='lineage'&&<Lineage object={object} source={source}/>} {tab==='yaml'&&(source.yaml?<CodePanel title={source.file} code={source.yaml}/>:<PolicyHidden label="Raw model YAML"/>)}</section></>}

type ObjectDraft={
  sourceMode:'table'|'select';
  metadata:{name:string;domain:string;label:string;description:string;owner:string;tags:string[]};
  spec:{
    source:{catalog:string;schema:string;table:string;select:string};
    primaryKey:string[];
    dimensions:Dimension[];
    relationships:Relationship[];
  };
};

function emptyObjectDraft(domain:string):ObjectDraft{
  return {
    sourceMode:'table',
    metadata:{name:'',domain,label:'',description:'',owner:'',tags:[]},
    spec:{
      source:{catalog:'postgres',schema:'public',table:'',select:''},
      primaryKey:[],
      dimensions:[],
      relationships:[]
    }
  };
}

function ObjectEditor(){
  const{id}=useParams(),isNew=id==='new',navigate=useNavigate();
  const[model,setModel]=useState<ModelSummary>(),[objects,setObjects]=useState<SemanticObject[]>([]),[metrics,setMetrics]=useState<Metric[]>([]),[draft,setDraft]=useState<ObjectDraft>(),[objectFile,setObjectFile]=useState(''),[original,setOriginal]=useState(''),[warning,setWarning]=useState(''),[saving,setSaving]=useState(false),[sourceHidden,setSourceHidden]=useState(false);
  useEffect(()=>{Promise.all([api<ModelSummary>('/model'),api<SemanticObject[]>('/objects'),api<Metric[]>('/metrics'),isNew?Promise.resolve(undefined):api<SemanticObject>('/objects/'+id),isNew?Promise.resolve(undefined):api<ObjectSource>('/objects/'+id+'/source')]).then(([m,allObjects,allMetrics,existing,source])=>{setModel(m);setObjects(allObjects);setMetrics(allMetrics);const next:ObjectDraft=existing?{sourceMode:existing.spec.source.select?'select':'table',metadata:{name:existing.metadata.name,domain:existing.metadata.domain,label:existing.metadata.label||'',description:existing.metadata.description||'',owner:existing.metadata.owner||'',tags:existing.metadata.tags||[]},spec:{source:{catalog:existing.spec.source.catalog||'postgres',schema:existing.spec.source.schema||'public',table:existing.spec.source.table||'',select:existing.spec.source.select||''},primaryKey:[...existing.spec.primaryKey],dimensions:existing.spec.dimensions.map(d=>({...d})),relationships:existing.spec.relationships.map(r=>({...r,sourceFields:[...r.sourceFields],targetFields:[...r.targetFields]}))}}:emptyObjectDraft(m.domains[0]?.key||'retail');setDraft(next);setOriginal(JSON.stringify(next));setObjectFile(source?.file||'');if(existing&&!source?.yaml){setSourceHidden(true);setWarning('Physical source hidden by policy. Editing this object requires physical lineage access.')}}).catch(e=>setWarning(e.message))},[id,isNew]);
  const objectDocument=useMemo(()=>draft?{version:1,kind:'object',metadata:draft.metadata,spec:{...draft.spec,source:draft.sourceMode==='select'?{select:draft.spec.source.select}:{catalog:draft.spec.source.catalog,schema:draft.spec.source.schema,table:draft.spec.source.table}}}:undefined,[draft]);
  const generatedYaml=useMemo(()=>objectDocument?YAML.stringify(objectDocument):'',[objectDocument]);
  const dirty=Boolean(draft&&JSON.stringify(draft)!==original);
  useEffect(()=>{const guard=(event:BeforeUnloadEvent)=>{if(dirty)event.preventDefault()};addEventListener('beforeunload',guard);return()=>removeEventListener('beforeunload',guard)},[dirty]);
  if(!draft||!model)return <Loading label="Loading object builder"/>;
  const ownMetrics=metrics.filter(metric=>baseObjectId(metric)===id);
  const incoming=objects.filter(object=>objectId(object)!==id&&object.spec.relationships.some(relation=>relation.targetObject===id));
  const blockers=[...ownMetrics.map(metric=>'Metric: '+metric.metadata.name),...incoming.map(object=>'Relationship from: '+object.metadata.name)];
  const updateMetadata=(key:string,value:unknown)=>setDraft(current=>current&&({...current,metadata:{...current.metadata,[key]:value}}));
  const updateSource=(key:string,value:string)=>setDraft(current=>current&&({...current,spec:{...current.spec,source:{...current.spec.source,[key]:value}}}));
  const setSourceMode=(sourceMode:'table'|'select')=>setDraft(current=>current&&({...current,sourceMode}));
  const setDimensions=(dimensions:Dimension[])=>setDraft(current=>current&&({...current,spec:{...current.spec,dimensions}}));
  const setRelationships=(relationships:Relationship[])=>setDraft(current=>current&&({...current,spec:{...current.spec,relationships}}));
  const addDimension=()=>{const name='field_'+(draft.spec.dimensions.length+1);setDimensions([...draft.spec.dimensions,{name,label:'',description:'',type:'varchar',sql:name,nullable:true}])};
  const updateDimension=(index:number,key:string,value:unknown)=>{
    const previous=draft.spec.dimensions[index].name;
    setDraft(current=>current&&({...current,spec:{...current.spec,dimensions:current.spec.dimensions.map((dimension,i)=>i===index?{...dimension,[key]:value}:dimension),primaryKey:key==='name'?current.spec.primaryKey.map(field=>field===previous?String(value):field):current.spec.primaryKey}}));
  };
  const removeDimension=(index:number)=>{const removed=draft.spec.dimensions[index].name;setDraft(current=>current&&({...current,spec:{...current.spec,dimensions:current.spec.dimensions.filter((_,i)=>i!==index),primaryKey:current.spec.primaryKey.filter(field=>field!==removed)}}))};
  const togglePrimaryKey=(field:string,checked:boolean)=>setDraft(current=>current&&({...current,spec:{...current.spec,primaryKey:checked?[...new Set([...current.spec.primaryKey,field])]:current.spec.primaryKey.filter(value=>value!==field)}}));
  const addRelationship=()=>{const target=objects.find(object=>objectId(object)!==`${draft.metadata.domain}.${draft.metadata.name}`);setRelationships([...draft.spec.relationships,{name:'relationship_'+(draft.spec.relationships.length+1),targetObject:target?objectId(target):'',sourceFields:[],targetFields:[],cardinality:'many_to_one',defaultJoinType:'left'}])};
  const updateRelationship=(index:number,key:string,value:unknown)=>setRelationships(draft.spec.relationships.map((relationship,i)=>i===index?{...relationship,[key]:value}:relationship));
  const errors=[!draft.metadata.name&&'Technical name is required',draft.metadata.name&&!/^[a-z][a-z0-9_]*$/.test(draft.metadata.name)&&'Technical name must use lowercase_snake_case',!draft.metadata.domain&&'Domain is required',!draft.metadata.label&&'Label is required',!draft.metadata.description&&'Description is required',!draft.metadata.owner&&'Owner is required',draft.sourceMode==='table'&&!draft.spec.source.catalog&&'Source catalog is required',draft.sourceMode==='table'&&!draft.spec.source.schema&&'Source schema is required',draft.sourceMode==='table'&&!draft.spec.source.table&&'Source table is required',draft.sourceMode==='select'&&!draft.spec.source.select.trim()&&'Source SELECT is required',draft.spec.dimensions.length===0&&'Add at least one dimension',...draft.spec.dimensions.flatMap((dimension,index)=>[!dimension.name&&`Dimension ${index+1}: name is required`,!dimension.type&&`Dimension ${index+1}: type is required`,!dimension.sql&&`Dimension ${index+1}: SQL expression is required`]),...draft.spec.relationships.flatMap((relationship,index)=>[!relationship.name&&`Relationship ${index+1}: name is required`,!relationship.targetObject&&`Relationship ${index+1}: target is required`,relationship.sourceFields.length===0&&`Relationship ${index+1}: source fields are required`,relationship.targetFields.length===0&&`Relationship ${index+1}: target fields are required`])].filter(Boolean) as string[];
  const save=async()=>{if(sourceHidden){setWarning('Physical source hidden by policy. Editing this object requires physical lineage access.');return}if(errors.length||!objectDocument){setWarning(errors[0]||'Object definition is incomplete');return}setSaving(true);setWarning('');try{if(model.governanceMode==='governed'){const file=`domains/${draft.metadata.domain}/objects/${draft.metadata.name}.yaml`;sessionStorage.setItem('semantic-change-draft',JSON.stringify({file,text:generatedYaml,title:(isNew?'Create ':'Update ')+draft.metadata.name,description:draft.metadata.description,moveFrom:!isNew&&objectFile!==file?objectFile:undefined}));navigate('/changes')}else{const saved=await api<SemanticObject>(isNew?'/objects':'/objects/'+id,{method:isNew?'POST':'PUT',body:JSON.stringify({metadata:objectDocument.metadata,spec:objectDocument.spec})});setOriginal(JSON.stringify(draft));navigate('/objects/'+objectId(saved))}}catch(e){setWarning(e instanceof Error?e.message:String(e))}finally{setSaving(false)}};
  const remove=async()=>{if(isNew)return;if(blockers.length){setWarning('Remove dependent metrics and incoming relationships first: '+blockers.join(', '));return}if(!confirm(`Delete object ${draft.metadata.name}?`))return;if(model.governanceMode==='governed'){sessionStorage.setItem('semantic-change-draft',JSON.stringify({file:objectFile,text:'',title:'Delete '+draft.metadata.name,description:'Remove semantic object '+draft.metadata.name,deletion:true}));navigate('/changes')}else{try{await api('/objects/'+id,{method:'DELETE'});navigate('/')}catch(e){setWarning(e instanceof Error?e.message:String(e))}}};
  return <><PageHeader eyebrow={isNew?'Create object':`Edit object · ${draft.metadata.domain}`} title={isNew?'Create a semantic object':draft.metadata.label||draft.metadata.name} description="Use the visual builder. Witness generates the YAML specification automatically." actions={!isNew&&<button className="button danger" disabled={blockers.length>0} title={blockers.length?'Remove dependencies before deleting':''} onClick={remove}>{model.governanceMode==='governed'?'Propose deletion':'Delete object'}</button>}/><div className="editor-layout object-builder"><section className="panel editor-form"><PanelTitle title="Object identity" meta={<span className={'mode-badge '+model.governanceMode}>{model.governanceMode==='governed'?'MR governed':'Local development'}</span>}/><div className="form-row"><label>Technical name<input disabled={!isNew} value={draft.metadata.name} onChange={e=>updateMetadata('name',e.target.value)} placeholder="customer_profiles"/></label><label>Domain<select value={draft.metadata.domain} onChange={e=>updateMetadata('domain',e.target.value)}>{model.domains.map(domain=><option key={domain.key} value={domain.key}>{domain.label}</option>)}</select></label></div><div className="form-row"><label>Label<input value={draft.metadata.label} onChange={e=>updateMetadata('label',e.target.value)} placeholder="Customer profiles"/></label><label>Owner<input value={draft.metadata.owner} onChange={e=>updateMetadata('owner',e.target.value)} placeholder="customer-platform"/></label></div><label>Description<textarea value={draft.metadata.description} onChange={e=>updateMetadata('description',e.target.value)} placeholder="Explain the business meaning and intended use."/></label><label>Tags<input value={draft.metadata.tags.join(', ')} onChange={e=>updateMetadata('tags',e.target.value.split(',').map(value=>value.trim()).filter(Boolean))} placeholder="customer, master-data"/></label><section className="builder-section source-builder"><PanelTitle title="Object source" meta={<div className="source-mode-switch"><button className={draft.sourceMode==='table'?'active':''} onClick={()=>setSourceMode('table')}>Physical table</button><button className={draft.sourceMode==='select'?'active':''} onClick={()=>setSourceMode('select')}>SQL select</button></div>}/>{draft.sourceMode==='table'?<div className="form-row three"><label>Trino catalog<input value={draft.spec.source.catalog} onChange={e=>updateSource('catalog',e.target.value)} placeholder="postgres"/></label><label>Schema<input value={draft.spec.source.schema} onChange={e=>updateSource('schema',e.target.value)} placeholder="public"/></label><label>Table<input value={draft.spec.source.table} onChange={e=>updateSource('table',e.target.value)} placeholder="customers"/></label></div>:<><label>Source SELECT<textarea className="source-select-editor" aria-label="Source SELECT" spellCheck={false} value={draft.spec.source.select} onChange={e=>updateSource('select',e.target.value)} placeholder={'SELECT\n  o.order_id,\n  c.country\nFROM postgres.public.orders o\nLEFT JOIN postgres.public.customers c\n  ON c.customer_id = o.customer_id'}/></label><div className="callout info"><Icon name="code"/><p>Use one read-only SELECT. Physical tables must be fully qualified as catalog.schema.table. Dimension SQL expressions reference the output column names of this SELECT.</p></div></>}</section><section className="builder-section"><PanelTitle title="Dimensions" meta={<button className="text-button" onClick={addDimension}>+ Add dimension</button>}/>{draft.spec.dimensions.length===0?<Empty title="No dimensions yet" body="Add the columns that should be exposed through the semantic object."/>:<div className="builder-list">{draft.spec.dimensions.map((dimension,index)=><div className="builder-card" key={index}><div className="builder-card-title"><strong>Dimension {index+1}</strong><button className="icon-button" aria-label="Remove dimension" onClick={()=>removeDimension(index)}><Icon name="close" size={15}/></button></div><div className="builder-dimension-grid"><label>Name<input value={dimension.name} onChange={e=>updateDimension(index,'name',e.target.value)}/></label><label>Label<input value={dimension.label||''} onChange={e=>updateDimension(index,'label',e.target.value)}/></label><label>Type<select value={dimension.type} onChange={e=>updateDimension(index,'type',e.target.value)}>{['bigint','integer','double','boolean','date','timestamp','varchar','decimal(18,2)'].map(type=><option key={type}>{type}</option>)}</select></label><label>SQL expression<input value={dimension.sql} onChange={e=>updateDimension(index,'sql',e.target.value)}/></label></div><label>Description<input value={dimension.description||''} onChange={e=>updateDimension(index,'description',e.target.value)}/></label><div className="builder-checks"><label className="check-label"><input type="checkbox" checked={dimension.nullable!==false} onChange={e=>updateDimension(index,'nullable',e.target.checked)}/>Nullable</label><label className="check-label"><input type="checkbox" checked={draft.spec.primaryKey.includes(dimension.name)} onChange={e=>togglePrimaryKey(dimension.name,e.target.checked)}/>Primary key</label></div></div>)}</div>}</section><section className="builder-section"><PanelTitle title="Relationships" meta={<button className="text-button" onClick={addRelationship}>+ Add relationship</button>}/>{draft.spec.relationships.length===0?<p className="muted">No joins declared. Relationships can be added later.</p>:<div className="builder-list">{draft.spec.relationships.map((relationship,index)=><div className="builder-card" key={index}><div className="builder-card-title"><strong>Relationship {index+1}</strong><button className="icon-button" aria-label="Remove relationship" onClick={()=>setRelationships(draft.spec.relationships.filter((_,i)=>i!==index))}><Icon name="close" size={15}/></button></div><div className="builder-relationship-grid"><label>Name<input value={relationship.name} onChange={e=>updateRelationship(index,'name',e.target.value)}/></label><label>Target object<select value={relationship.targetObject} onChange={e=>updateRelationship(index,'targetObject',e.target.value)}><option value="">Select object</option>{objects.filter(object=>objectId(object)!==`${draft.metadata.domain}.${draft.metadata.name}`).map(object=><option key={objectId(object)} value={objectId(object)}>{object.metadata.domain}.{object.metadata.name}</option>)}</select></label><label>Source fields<input value={relationship.sourceFields.join(', ')} onChange={e=>updateRelationship(index,'sourceFields',e.target.value.split(',').map(value=>value.trim()).filter(Boolean))} placeholder="customer_id"/></label><label>Target fields<input value={relationship.targetFields.join(', ')} onChange={e=>updateRelationship(index,'targetFields',e.target.value.split(',').map(value=>value.trim()).filter(Boolean))} placeholder="customer_id"/></label><label>Cardinality<select value={relationship.cardinality} onChange={e=>updateRelationship(index,'cardinality',e.target.value)}>{['one_to_one','one_to_many','many_to_one','many_to_many'].map(value=><option key={value}>{value}</option>)}</select></label><label>Join type<select value={relationship.defaultJoinType} onChange={e=>updateRelationship(index,'defaultJoinType',e.target.value)}>{['left','inner','right','full'].map(value=><option key={value}>{value}</option>)}</select></label></div></div>)}</div>}</section>{warning&&<ErrorState message={warning}/>}<div className="form-actions"><button className="button subtle" onClick={()=>{if(!dirty||confirm('Discard unsaved changes?'))navigate(isNew?'/':'/objects/'+id)}}>Discard</button><button className="button primary" disabled={saving} onClick={save}>{saving?'Saving…':model.governanceMode==='governed'?'Review generated YAML':'Save object'}</button></div></section><aside className="editor-aside"><CodePanel title="Generated object YAML" code={generatedYaml} dark/><section className="panel"><PanelTitle title="Deletion safety"/>{isNew?<p className="muted">Dependencies are checked after the object is created.</p>:blockers.length===0?<div className="callout info"><Icon name="check"/><p>No dependent metrics or incoming relationships. This object can be proposed for deletion.</p></div>:<><div className="callout warning"><Icon name="warning"/><p>Remove these dependencies before deleting the object.</p></div><ul className="dependency-list">{blockers.map(blocker=><li key={blocker}>{blocker}</li>)}</ul></>}</section>{errors.length>0&&<section className="panel"><PanelTitle title="Required before review"/><ul className="dependency-list error-list">{errors.slice(0,6).map(error=><li key={error}>{error}</li>)}</ul></section>}</aside></div></>
}
function PolicyHidden({label}:{label:string}){return <div className="callout info"><Icon name="warning"/><p><strong>{label} hidden by policy.</strong><br/>Enable physical lineage or compiled SQL exposure to view it.</p></div>}
function ObjectOverview({object,source}:{object:SemanticObject;source:ObjectSource}){return <div className="detail-grid"><section className="panel"><PanelTitle title="Business context"/><p className="lead">{object.metadata.description}</p><dl><dt>Owner</dt><dd>{object.metadata.owner||'Not assigned'}</dd><dt>Domain</dt><dd><span className="domain-chip">{object.metadata.domain}</span></dd><dt>Primary grain</dt><dd>{object.spec.primaryKey.map(x=><code key={x}>{x}</code>)}</dd><dt>Source file</dt><dd><code>{object.file}</code></dd></dl></section><section className="panel"><PanelTitle title="Physical lineage"/>{source.physicalSource?<><div className="lineage-path"><span>Semantic object</span><code>{object.metadata.domain}.{object.metadata.name}</code><Icon name="arrow"/><span>Trino source</span><code>{source.physicalSource}</code></div><div className="callout info"><Icon name="check"/><p>Only the registered semantic object is queryable. The physical source remains governed and hidden from pgwire clients.</p></div></>:<PolicyHidden label="Physical lineage"/>}</section></div>}
function PanelTitle({title,meta}:{title:string;meta?:ReactNode}){return <div className="panel-title"><h2>{title}</h2>{meta}</div>}
function DimensionsTable({object}:{object:SemanticObject}){return <div className="table-panel"><table><thead><tr><th scope="col">Dimension</th><th scope="col">Type</th><th scope="col">Expression</th><th scope="col">Nullable</th><th scope="col">Key</th></tr></thead><tbody>{object.spec.dimensions.map(d=><tr key={d.name}><td><strong>{d.label||d.name}</strong><code>{d.name}</code>{d.description&&<small>{d.description}</small>}</td><td><span className="type-pill">{d.type}</span></td><td><code>{d.sql}</code></td><td>{d.nullable===false?'No':'Yes'}</td><td>{object.spec.primaryKey.includes(d.name)&&<span className="key-pill">Primary key</span>}</td></tr>)}</tbody></table></div>}
function ObjectMetrics({object,metrics}:{object:SemanticObject;metrics:Metric[]}){return <section className="panel"><PanelTitle title="Metrics" meta={<Link className="button primary small" to={`/objects/${objectId(object)}/metrics/new`}>Create metric</Link>}/>{metrics.length===0?<Empty title="No metrics yet" body="Create the first governed measure for this object."/>:<div className="metric-list">{metrics.map(m=><Link to={`/objects/${objectId(object)}/metrics/${metricId(m)}`} key={metricId(m)}><span className="metric-glyph">ƒ</span><div><strong>{m.metadata.label||m.metadata.name}</strong><code>{m.metadata.name}</code><p>{m.metadata.description}</p></div><span className="metric-formula">{m.spec.aggregation}({m.spec.expression})</span><Icon name="arrow"/></Link>)}</div>}</section>}
function Relationships({object}:{object:SemanticObject}){return <section className="panel"><PanelTitle title="Declared relationships"/>{object.spec.relationships.length===0?<Empty title="No relationships" body="This object does not declare any semantic joins."/>:<div className="relationship-list">{object.spec.relationships.map(r=><div key={r.name}><span className="relation-line"><code>{object.metadata.name}</code><b>{r.cardinality.replaceAll('_',' → ')}</b><Link to={'/objects/'+r.targetObject}><code>{r.targetObject}</code></Link></span><p>{r.sourceFields.join(', ')} → {r.targetFields.join(', ')} · {r.defaultJoinType} join</p></div>)}</div>}</section>}
function Lineage({object,source}:{object:SemanticObject;source:ObjectSource}){return <div className="detail-grid lineage-grid"><section className="panel"><PanelTitle title="Object lineage"/>{source.physicalSource?<div className="lineage-stack"><div><small>Semantic object</small><code>{object.metadata.domain}.{object.metadata.name}</code></div><span>↓ resolves through Trino ↓</span><div><small>Physical source</small><code>{source.physicalSource}</code></div></div>:<PolicyHidden label="Physical lineage"/>}</section><section className="panel"><PanelTitle title="Field mappings"/><div className="mapping-list">{source.fields.map(f=><div key={f.dimension}><code>{f.dimension}</code><Icon name="arrow"/><code>{f.expression}</code></div>)}</div></section></div>}
function CodePanel({title,code,dark=false}:{title:string;code:string;dark?:boolean}){const[copied,setCopied]=useState(false);const copy=()=>navigator.clipboard?.writeText(code).then(()=>{setCopied(true);setTimeout(()=>setCopied(false),1200)});return <section className={'code-panel '+(dark?'dark':'')}><header><span>{title}</span><button onClick={copy}><Icon name="copy" size={14}/>{copied?'Copied':'Copy'}</button></header><pre>{code}</pre></section>}

type MetricDraft={metadata:{name:string;domain:string;label:string;description:string;owner:string;tags:string[]};spec:{baseObject:string;aggregation:string;expression:string;resultType:string;format:string;filters:MetricFilter[]}};
function MetricEditor(){const{id,metric}=useParams();const isNew=metric==='new';const navigate=useNavigate();const[object,setObject]=useState<SemanticObject>(),[model,setModel]=useState<ModelSummary>(),[metricFile,setMetricFile]=useState(''),[draft,setDraft]=useState<MetricDraft>(),[original,setOriginal]=useState(''),[issues,setIssues]=useState<string[]>([]),[warning,setWarning]=useState(''),[saving,setSaving]=useState(false);const dirty=Boolean(draft&&JSON.stringify(draft)!==original);useEffect(()=>{Promise.all([api<SemanticObject>('/objects/'+id),api<ModelSummary>('/model'),isNew?Promise.resolve(undefined):api<Metric>('/metrics/'+metric)]).then(([o,m,existing])=>{setObject(o);setModel(m);setMetricFile(existing?.file||'');const next:MetricDraft=existing?{metadata:{name:existing.metadata.name,domain:existing.metadata.domain,label:existing.metadata.label||'',description:existing.metadata.description||'',owner:existing.metadata.owner||'',tags:existing.metadata.tags||[]},spec:{...existing.spec,filters:existing.spec.filters||[]}}:{metadata:{name:'',domain:o.metadata.domain,label:'',description:'',owner:'',tags:[]},spec:{baseObject:objectId(o),aggregation:'sum',expression:'',resultType:'decimal(18,2)',format:'number',filters:[]}};setDraft(next);setOriginal(JSON.stringify(next))})},[id,metric,isNew]);useEffect(()=>{const guard=(e:BeforeUnloadEvent)=>{if(dirty)e.preventDefault()};addEventListener('beforeunload',guard);return()=>removeEventListener('beforeunload',guard)},[dirty]);useEffect(()=>{if(!draft?.spec.expression)return;const timer=setTimeout(()=>api<ValidationResponse>('/validate',{method:'POST',body:JSON.stringify({expression:draft.spec.expression,objectId:id,aggregation:draft.spec.aggregation})}).then(r=>setIssues(r.errors.map(e=>e.message))).catch(e=>setIssues([e.message])),450);return()=>clearTimeout(timer)},[draft?.spec.expression,draft?.spec.aggregation,id]);if(!draft||!object||!model)return <Loading label="Loading metric editor"/>;const generatedYaml=YAML.stringify({version:1,kind:'metric',metadata:draft.metadata,spec:draft.spec});const updateMeta=(key:string,value:unknown)=>setDraft(d=>d&&({...d,metadata:{...d.metadata,[key]:value}}));const updateSpec=(key:string,value:unknown)=>setDraft(d=>d&&({...d,spec:{...d.spec,[key]:value}}));const nameError=!draft.metadata.name?'Name is required':!/^[a-z][a-z0-9_]*$/.test(draft.metadata.name)?'Use lowercase_snake_case and start with a letter':'';const hardErrors=[nameError,!draft.metadata.label&&'Label is required',!draft.metadata.description&&'Description is required for a verifiable metric',!draft.spec.expression&&'Expression is required',...issues].filter(Boolean) as string[];const save=async()=>{if(hardErrors.length)return;setSaving(true);try{if(model.governanceMode==='governed'){const path=isNew?`domains/${draft.metadata.domain}/metrics/${draft.metadata.name}.yaml`:metricFile;sessionStorage.setItem('semantic-change-draft',JSON.stringify({file:path,text:generatedYaml,title:(isNew?'Create ':'Update ')+draft.metadata.name,description:draft.metadata.description}));navigate('/changes')}else{const saved=await api<Metric>(isNew?'/metrics':'/metrics/'+metric,{method:isNew?'POST':'PUT',body:JSON.stringify(draft)});setOriginal(JSON.stringify(draft));navigate(`/objects/${baseObjectId(saved)}/metrics/${metricId(saved)}`)}}catch(e){setWarning(e instanceof Error?e.message:String(e))}finally{setSaving(false)}};const remove=async()=>{if(isNew)return;if(model.governanceMode==='governed'){sessionStorage.setItem('semantic-change-draft',JSON.stringify({file:metricFile,text:'',title:'Delete '+draft.metadata.name,description:'Propose metric deletion',deletion:true}));navigate('/changes')}else if(confirm(`Delete metric ${draft.metadata.name}?`)){await api('/metrics/'+metric,{method:'DELETE'});navigate('/metrics')}};return <><PageHeader eyebrow={`${isNew?'Create':'Metric'} · ${object.metadata.domain}`} title={isNew?'Create a governed metric':draft.metadata.label||draft.metadata.name} description={isNew?`This metric will be exposed as a column on ${object.metadata.domain}.${object.metadata.name}.`:draft.metadata.description} actions={!isNew&&<button className="button danger" onClick={remove}>{model.governanceMode==='governed'?'Propose deletion':'Delete metric'}</button>}/><div className="editor-layout"><section className="panel editor-form"><PanelTitle title="Metric definition" meta={<span className={'mode-badge '+model.governanceMode}>{model.governanceMode==='governed'?'MR governed':'Local development'}</span>}/><label>Technical name<input disabled={!isNew} value={draft.metadata.name} onChange={e=>updateMeta('name',e.target.value)} onBlur={()=>nameError&&setWarning(nameError)} placeholder="gross_margin"/>{nameError&&<small className="field-error">{nameError}</small>}</label><div className="form-row"><label>Label<input value={draft.metadata.label} onChange={e=>updateMeta('label',e.target.value)} placeholder="Gross margin"/></label><label>Domain<input readOnly value={draft.metadata.domain}/></label></div><label>Description<textarea value={draft.metadata.description} onChange={e=>updateMeta('description',e.target.value)} placeholder="Explain the business meaning and intended use."/>{!draft.metadata.description&&<small className="field-error">Required for a verifiable metric</small>}</label><div className="form-row"><label>Owner<input value={draft.metadata.owner} onChange={e=>updateMeta('owner',e.target.value)} placeholder="finance-analytics"/></label><label>Tags<input value={draft.metadata.tags.join(', ')} onChange={e=>updateMeta('tags',e.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder="finance, revenue"/></label></div><div className="form-row three"><label>Aggregation<select value={draft.spec.aggregation} onChange={e=>updateSpec('aggregation',e.target.value)}>{['sum','count','count_distinct','min','max','avg','custom'].map(x=><option key={x}>{x}</option>)}</select></label><label>Result type<input value={draft.spec.resultType} onChange={e=>updateSpec('resultType',e.target.value)}/></label><label>Format<select value={draft.spec.format} onChange={e=>updateSpec('format',e.target.value)}>{['number','decimal','currency','percent','duration'].map(x=><option key={x}>{x}</option>)}</select></label></div><label>Expression<div className="code-input"><span>ƒ</span><input value={draft.spec.expression} onChange={e=>updateSpec('expression',e.target.value)} placeholder="amount"/></div>{issues.map(issue=><small className="field-error" key={issue}>{issue}</small>)}{draft.spec.expression&&!issues.length&&<small className="field-success"><Icon name="check" size={12}/>Expression resolves against {object.metadata.name}</small>}</label><FilterEditor filters={draft.spec.filters} dimensions={object.spec.dimensions.map(d=>d.name)} onChange={filters=>updateSpec('filters',filters)}/>{warning&&<ErrorState message={warning}/>}<div className="form-actions"><button className="button subtle" onClick={()=>{if(!dirty||confirm('Discard unsaved changes?'))navigate(-1)}}>Discard</button><button className="button primary" disabled={hardErrors.length>0||saving} onClick={save}>{saving?'Saving…':model.governanceMode==='governed'?'Review & open MR':'Save metric'}</button></div></section><aside className="editor-aside"><CodePanel title="Generated metric YAML" code={generatedYaml} dark/><section className="panel"><PanelTitle title="Column preview"/><div className="column-preview"><span className="metric-glyph">ƒ</span><div><strong>{draft.metadata.label||'Untitled metric'}</strong><code>{draft.metadata.name||'metric_name'}</code></div><span className="type-pill">{draft.spec.resultType}</span></div><dl><dt>Virtual table</dt><dd><code>{object.metadata.domain}.{object.metadata.name}</code></dd><dt>Formula</dt><dd><code>{draft.spec.aggregation}({draft.spec.expression||'…'})</code></dd><dt>Status</dt><dd>{hardErrors.length?<span className="warning-badge"><Icon name="warning" size={12}/>{hardErrors.length} issues</span>:<Verified/>}</dd></dl></section><div className="callout info"><Icon name="branch"/><p>{model.governanceMode==='governed'?'Saving stages a YAML change. The active model changes only after GitLab review, merge, and reload.':'Local development mode writes validated YAML and reloads the model immediately.'}</p></div></aside></div></>}
function FilterEditor({filters,dimensions,onChange}:{filters:MetricFilter[];dimensions:string[];onChange:(f:MetricFilter[])=>void}){const add=()=>onChange([...filters,{field:dimensions[0]||'',operator:'eq',values:[]}]);const update=(index:number,key:string,value:unknown)=>onChange(filters.map((f,i)=>i===index?{...f,[key]:value}:f));return <div className="filter-editor"><div className="panel-title"><h3>Metric filters</h3><button className="text-button" onClick={add}>+ Add filter</button></div>{filters.length===0?<p className="muted">No filters. The metric aggregates all eligible rows.</p>:filters.map((f,i)=><div className="filter-row" key={i}><select aria-label="Filter field" value={f.field} onChange={e=>update(i,'field',e.target.value)}>{dimensions.map(d=><option key={d}>{d}</option>)}</select><select aria-label="Filter operator" value={f.operator} onChange={e=>update(i,'operator',e.target.value)}>{['eq','neq','in','not_in','gt','gte','lt','lte','is_null','is_not_null'].map(x=><option key={x}>{x}</option>)}</select><input aria-label="Filter values" disabled={f.operator.startsWith('is_')} value={f.values.join(', ')} onChange={e=>update(i,'values',e.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder="value, value"/><button className="icon-button" aria-label="Remove filter" onClick={()=>onChange(filters.filter((_,x)=>x!==i))}><Icon name="close" size={15}/></button></div>)}</div>}

function QueryWorkspace(){const[objects,setObjects]=useState<SemanticObject[]>([]),[metrics,setMetrics]=useState<Metric[]>([]),[params]=useSearchParams();const[sql,setSql]=useState('SELECT customer_id, total_revenue\nFROM retail.orders\nGROUP BY customer_id\nORDER BY total_revenue DESC\nLIMIT 100;'),[result,setResult]=useState<QueryResponse>(),[error,setError]=useState<{message:string;hint?:string}>(),[running,setRunning]=useState(false),[expanded,setExpanded]=useState(false);const abort=useRef<AbortController>();useEffect(()=>{Promise.all([api<SemanticObject[]>('/objects'),api<Metric[]>('/metrics')]).then(([o,m])=>{setObjects(o);setMetrics(m);const selected=params.get('object');if(selected){const object=o.find(x=>objectId(x)===selected);if(object)setSql(`SELECT *\nFROM ${object.metadata.domain}.${object.metadata.name}\nLIMIT 100;`)}})},[params]);const run=async()=>{abort.current=new AbortController();setRunning(true);setError(undefined);try{setResult(await api<QueryResponse>('/query',{method:'POST',body:JSON.stringify({sql}),signal:abort.current.signal}))}catch(e){if((e as Error).name!=='AbortError')setError({message:(e as Error).message,hint:(e as Error&{hint?:string}).hint})}finally{setRunning(false)}};return <><PageHeader eyebrow="Query workspace" title="Query the semantic model" description="PostgreSQL SELECT is validated, compiled, and executed by Trino." actions={<button className="button primary run" disabled={running} onClick={run}>{running?<span className="spinner small"/>:<span>▶</span>}Run query</button>}/><div className="query-layout"><aside className="schema-tree"><header><strong>Schema</strong><small>Active model</small></header>{[...new Set(objects.map(o=>o.metadata.domain))].map(domain=><details key={domain} open><summary><span className="schema-icon">S</span><code>{domain}</code></summary>{objects.filter(o=>o.metadata.domain===domain).map(o=><details key={objectId(o)}><summary><Icon name="table" size={14}/><code>{o.metadata.name}</code></summary><ul>{o.spec.dimensions.map(d=><li key={d.name}><span className="column-dot"/><code>{d.name}</code><small>{d.type}</small></li>)}{metrics.filter(m=>metricBelongsTo(m,o)).map(m=><li className="metric-column" key={metricId(m)}><span className="metric-glyph tiny">ƒ</span><code>{m.metadata.name}</code><small>{m.spec.resultType}</small></li>)}</ul></details>)}</details>)}</aside><section className="query-main"><div className="sql-editor"><header><span>SQL editor</span><small>SELECT only</small></header><textarea spellCheck={false} aria-label="SQL editor" value={sql} onChange={e=>setSql(e.target.value)}/><footer><span>PostgreSQL semantic SQL</span><span>{sql.length} chars</span></footer></div>{running&&<div className="query-progress" role="status"><span className="spinner"/><div><strong>Compiling to Trino · executing</strong><small>Validating registered objects and metric semantics</small></div><button className="button subtle small" onClick={()=>abort.current?.abort()}>Cancel</button></div>}{error&&<ErrorState message={error.message} hint={error.hint}/>} {!running&&!error&&!result&&<Empty title="Run a semantic query" body="Results, timing, and compiled Trino SQL will appear here."/>}{result&&<section className={'results '+(running?'dimmed':'')} aria-live="polite"><header><div><strong>Results</strong><span className="success-badge"><Icon name="check" size={12}/>Success</span></div><p>{result.rowCount} rows · {result.elapsedMs} ms</p></header>{result.rowCount===0?<Empty title="0 rows returned" body="The query executed successfully but no rows matched."/>:<div className="results-scroll"><table><thead><tr>{result.columns.map(c=><th scope="col" key={c.name}>{c.name}<small>{c.typeName}</small></th>)}</tr></thead><tbody>{result.rows.map((row,i)=><tr key={i}>{row.map((value,j)=><td key={j}>{value===null?<span className="null">NULL</span>:String(value)}</td>)}</tr>)}</tbody></table></div>}{result.compiledTrinoSql?<><button className="compiled-toggle" onClick={()=>setExpanded(!expanded)}><Icon name="code" size={15}/>{expanded?'Hide':'Show'} compiled Trino SQL</button>{expanded&&<CodePanel title="Compiled Trino SQL" code={result.compiledTrinoSql} dark/>}</>:<PolicyHidden label="Compiled Trino SQL"/>}</section>}</section></div></>}

function SearchPage(){
  const[params,setParams]=useSearchParams();const q=params.get('q')||'';
  const[type,setType]=useState(params.get('type')||'all'),[domain,setDomain]=useState(params.get('domain')||'all'),[verified,setVerified]=useState(params.get('verified')==='true'),[input,setInput]=useState(q),[results,setResults]=useState<SearchResult[]>([]),[model,setModel]=useState<ModelSummary>(),[loading,setLoading]=useState(false);
  useEffect(()=>{api<ModelSummary>('/model').then(setModel)},[]);
  useEffect(()=>{setLoading(true);const query=new URLSearchParams({q});if(type!=='all')query.set('type',type);if(domain!=='all')query.set('domain',domain);if(verified)query.set('verifiedOnly','true');api<SearchResult[]>('/search?'+query).then(setResults).finally(()=>setLoading(false))},[q,type,domain,verified]);
  const submit=(e:FormEvent)=>{e.preventDefault();const next=new URLSearchParams(params);next.set('q',input);setParams(next)};
  const glyph=(item:SearchResult)=>item.type==='metric'?'ƒ':item.type==='dimension'?'D':'T';
  return <><PageHeader eyebrow="Global search" title="Find trusted semantics" description="Search objects, dimensions, and metrics across every domain."/><form className="search-hero" onSubmit={submit}><Icon name="search"/><input autoFocus value={input} onChange={e=>setInput(e.target.value)} placeholder="Search by name, label, owner or tag"/><button className="button primary">Search</button></form><div className="search-layout"><aside className="facets"><strong>Filter results</strong><label>Type<select value={type} onChange={e=>setType(e.target.value)}><option value="all">All types</option><option value="object">Objects</option><option value="dimension">Dimensions</option><option value="metric">Metrics</option></select></label><label>Domain<select value={domain} onChange={e=>setDomain(e.target.value)}><option value="all">All domains</option>{model?.domains.map(d=><option key={d.key} value={d.key}>{d.label}</option>)}</select></label><label className="check-label"><input type="checkbox" checked={verified} onChange={e=>setVerified(e.target.checked)}/>Verified only</label></aside><section className="search-results"><header><strong>{results.length} results</strong><span>{q&&<>for “{q}”</>}</span></header>{loading?<Loading label="Searching catalog"/>:results.length===0?<Empty title="No matches" body="Try a broader term or clear one of the filters."/>:results.map(item=><Link to={item.path} className="search-result" key={item.type+item.domain+item.name}><span className={'result-type '+item.type}>{glyph(item)}</span><div><span><strong>{item.label||item.name}</strong><code>{item.domain}.{item.name}</code></span><p>{item.snippet||'No description available'}</p><small>{item.owner||'No owner'} · {item.domain}</small></div><Verified value={item.verified}/><Icon name="arrow"/></Link>)}</section></div></>}

function ChangeWizard(){
  const[params]=useSearchParams();const objectTemplate=params.get('kind')==='object';
  const[step,setStep]=useState(0),[file,setFile]=useState(objectTemplate?'domains/retail/objects/new_object.yaml':'domains/retail/metrics/new_metric.yaml'),[text,setText]=useState(''),[deletion,setDeletion]=useState(false),[moveFrom,setMoveFrom]=useState(''),[title,setTitle]=useState(objectTemplate?'Create semantic object':'Create semantic metric'),[description,setDescription]=useState(''),[commit,setCommit]=useState(objectTemplate?'feat(semantic): add object':'feat(semantic): add metric'),[preview,setPreview]=useState<ChangePreview>(),[result,setResult]=useState<ChangeResult>(),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  useEffect(()=>{const stored=sessionStorage.getItem('semantic-change-draft');if(stored){const draft=JSON.parse(stored);setFile(draft.file);setText(draft.text||'');setDeletion(Boolean(draft.deletion));setMoveFrom(draft.moveFrom||'');setTitle(draft.title);setDescription(draft.description||'');setCommit((draft.deletion?'chore':'feat')+`(semantic): ${draft.title.toLowerCase()}`)}else if(objectTemplate)setText(YAML.stringify({version:1,kind:'object',metadata:{name:'new_object',domain:'retail',label:'New object',description:'Business object definition',owner:'analytics',tags:['draft']},spec:{source:{catalog:'postgres',schema:'public',table:'customers'},primaryKey:['customer_id'],dimensions:[{name:'customer_id',label:'Customer ID',description:'Stable customer identifier',type:'bigint',sql:'customer_id',nullable:false},{name:'name',label:'Customer name',description:'Customer display name',type:'varchar',sql:'name',nullable:false}],relationships:[]}}));else setText(YAML.stringify({version:1,kind:'metric',metadata:{name:'new_metric',domain:'retail',label:'New metric',description:'Business definition',owner:'analytics',tags:['draft']},spec:{baseObject:'orders',aggregation:'sum',expression:'amount',resultType:'decimal(18,2)',format:'number',filters:[]}}))},[objectTemplate]);
  const payload=(baseRevision?:string)=>({files:deletion?{}:{[file]:text},deletions:deletion?[file]:moveFrom?[moveFrom]:[],title,description,commitMessage:commit,...(baseRevision?{baseRevision}:{})});
  const validate=async()=>{setBusy(true);setError('');try{setPreview(await api<ChangePreview>('/changes/validate',{method:'POST',body:JSON.stringify(payload())}));setStep(1)}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
  const submit=async()=>{if(!preview?.validation.valid)return;setBusy(true);try{setResult(await api<ChangeResult>('/changes/submit',{method:'POST',body:JSON.stringify(payload(preview.baseRevision))}));sessionStorage.removeItem('semantic-change-draft');setStep(3)}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
  const branch='semantic/change/'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'').slice(0,36)+'-auto';
  return <><PageHeader eyebrow="Governed change" title="Create a semantic model change" description="One branch, one atomic commit, one Merge Request."/><ol className="stepper">{['Describe','Review diff','Branch & commit','Create MR'].map((name,i)=><li className={i===step?'active':i<step?'done':''} key={name}><span>{i<step?<Icon name="check" size={13}/>:i+1}</span><strong>{name}</strong></li>)}</ol>{error&&<ErrorState message={error}/>}<section className="wizard panel">
    {step===0&&<><PanelTitle title={deletion?'Describe the deletion':'Describe the change'}/><div className="form-row"><label>Change title<input value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Model file<input value={file} onChange={e=>setFile(e.target.value)}/></label></div><label>Merge Request description<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="What changes and why?"/></label>{moveFrom&&!deletion&&<div className="callout info"><Icon name="branch"/><p><strong>Move YAML file</strong><br/>{moveFrom} → {file}</p></div>}{deletion?<div className="callout warning"><Icon name="warning"/><p><strong>Delete {file}</strong><br/>The file is removed only after this Merge Request is reviewed and merged.</p></div>:<label>YAML definition<textarea className="yaml-editor" spellCheck={false} value={text} onChange={e=>setText(e.target.value)}/></label>}<div className="wizard-actions"><span>Draft is not active until merge and reload.</span><button className="button primary" disabled={busy||!title||(!deletion&&!text)} onClick={validate}>{busy?'Validating…':'Validate & review'}</button></div></>}
    {step===1&&preview&&<><PanelTitle title="Review proposed diff" meta={<span className={preview.validation.valid?'success-badge':'error-badge'}>{preview.validation.valid?'Validation passed':'Validation failed'}</span>}/><div className="validation-gates"><Gate pass={preview.validation.valid} label={deletion?'Deletion preserves model validity':'YAML schema valid'}/><Gate pass={preview.validation.valid} label="References resolve"/><Gate pass label="Base revision loaded"/></div>{preview.validation.errors.map((e,i)=><div className="validation-error" key={i}><code>{e.file}:{e.path}</code><strong>{e.message}</strong><span>{e.code}</span></div>)}<DiffView diff={preview.diff}/><div className="affected"><span>Affected objects: {preview.affectedObjects.join(', ')||'none'}</span><span>Affected metrics: {preview.affectedMetrics.join(', ')||'none'}</span></div><div className="wizard-actions"><button className="button subtle" onClick={()=>setStep(0)}>Back</button><button className="button primary" disabled={!preview.validation.valid} onClick={()=>setStep(2)}>Continue</button></div></>}
    {step===2&&preview&&<><PanelTitle title="Branch and commit"/><div className="branch-preview"><Icon name="branch"/><div><small>New branch from main</small><code>{branch}</code></div></div><label>Commit message<input value={commit} onChange={e=>setCommit(e.target.value)}/></label><div className="validation-gates vertical"><Gate pass label="Schema valid"/><Gate pass label="Semantic references resolve"/><Gate pass label={`Branch freshness checked at ${preview.baseRevision.slice(0,8)}`}/></div><div className="callout warning"><Icon name="warning"/><p>If main changes before submission, the API returns a conflict and asks you to refresh. Existing work is never overwritten.</p></div><div className="wizard-actions"><button className="button subtle" onClick={()=>setStep(1)}>Back</button><button className="button primary" disabled={busy||!commit} onClick={submit}>{busy?'Creating MR…':'Create Merge Request'}</button></div></>}
    {step===3&&result&&<div className="mr-success"><span className="success-orb"><Icon name="check" size={30}/></span><h2>Merge Request created</h2><p>Your proposal is ready for review. After merge, Witness follows main and refreshes the catalog automatically.</p><dl><dt>Branch</dt><dd><code>{result.branch}</code></dd><dt>Commit</dt><dd><code>{result.commitSha}</code></dd><dt>Merge Request</dt><dd>!{result.mergeRequest.id}</dd></dl><div><a className="button primary" href={result.mergeRequest.url} target="_blank" rel="noreferrer">Open in GitLab</a><Link className="button subtle" to="/">Back to catalog</Link></div></div>}
  </section></>}
function Gate({pass,label}:{pass?:boolean;label:string}){return <div className={pass===false?'fail':'pass'}><span>{pass===false?<Icon name="close" size={13}/>:<Icon name="check" size={13}/>}</span>{label}</div>}
function DiffView({diff}:{diff:string}){return <div className="diff"><header><span>YAML diff</span><small>{diff.split('\n').filter(x=>x.startsWith('+')||x.startsWith('-')).length} changed lines</small></header><pre>{diff.split('\n').map((line,i)=><span className={line.startsWith('+')?'added':line.startsWith('-')?'removed':'context'} key={i}><b>{line.startsWith('+')?'+':line.startsWith('-')?'−':' '}</b>{line}</span>)}</pre></div>}

function ConnectPage(){const[url]=useState('jdbc:postgresql://localhost:55433/semantic?sslmode=disable');const[tab,setTab]=useState('dbeaver'),[copied,setCopied]=useState('');const copy=(name:string,value:string)=>navigator.clipboard?.writeText(value).then(()=>{setCopied(name);setTimeout(()=>setCopied(''),1200)});return <><PageHeader eyebrow="Connect" title="Use the semantic layer as PostgreSQL" description="Discover domains as schemas and semantic objects as read-only tables."/><div className="connect-grid"><section className="panel connection-card"><div className="connection-title"><span className="postgres-mark">P</span><div><h2>PostgreSQL wire endpoint</h2><p>Compatible with pgjdbc and DBeaver</p></div><span className="success-badge"><span className="status-dot success"/>Available</span></div><dl><dt>JDBC URL</dt><dd><CopyValue value={url} copied={copied==='url'} onCopy={()=>copy('url',url)}/></dd><dt>Username</dt><dd><CopyValue value="semantic" copied={copied==='user'} onCopy={()=>copy('user','semantic')}/></dd><dt>Password</dt><dd><CopyValue value="semantic" copied={copied==='password'} onCopy={()=>copy('password','semantic')}/></dd><dt>Database</dt><dd><code>semantic</code></dd></dl><div className="callout warning"><Icon name="warning"/><p>These are local development credentials. Production credentials must never be displayed in the UI.</p></div></section><section className="panel schema-preview"><PanelTitle title="What clients discover"/><div className="mini-tree"><div><span className="db-icon">DB</span><code>semantic</code></div><div className="indent"><span className="schema-icon">S</span><code>retail</code></div><div className="indent two"><Icon name="table" size={14}/><code>orders</code></div><div className="indent three"><span className="column-dot"/><code>customer_id</code></div><div className="indent three metric"><span className="metric-glyph tiny">ƒ</span><code>total_revenue</code></div><div className="indent"><span className="schema-icon">S</span><code>ai_rnd</code></div></div></section></div><section className="panel guide"><nav className="tabs"><button className={tab==='dbeaver'?'active':''} onClick={()=>setTab('dbeaver')}>DBeaver</button><button className={tab==='jdbc'?'active':''} onClick={()=>setTab('jdbc')}>pgjdbc</button><button className={tab==='sql'?'active':''} onClick={()=>setTab('sql')}>Example SQL</button></nav>{tab==='dbeaver'&&<ol className="guide-steps"><li><span>1</span><div><strong>Create a PostgreSQL connection</strong><p>Choose PostgreSQL in DBeaver and paste the JDBC URL above.</p></div></li><li><span>2</span><div><strong>Enter local credentials</strong><p>Use semantic / semantic and disable SSL for local development.</p></div></li><li><span>3</span><div><strong>Refresh schemas</strong><p>Open Databases → semantic → Schemas. Use Invalidate/Reconnect if metadata was cached.</p></div></li></ol>}{tab==='jdbc'&&<CodePanel title="Java · pgjdbc" code={`var connection = DriverManager.getConnection(\n    "${url}",\n    "semantic", "semantic");`}/>} {tab==='sql'&&<CodePanel title="Semantic SQL" dark code={'SELECT customer_id, total_revenue\nFROM retail.orders\nGROUP BY customer_id\nORDER BY total_revenue DESC\nLIMIT 100;'}/>}</section></>}
function CopyValue({value,copied,onCopy}:{value:string;copied:boolean;onCopy:()=>void}){return <span className="copy-value"><code>{value}</code><button onClick={onCopy}><Icon name={copied?'check':'copy'} size={14}/>{copied?'Copied':'Copy'}</button></span>}

function Diagram(){const navigate=useNavigate();const[objects,setObjects]=useState<SemanticObject[]>([]),[domain,setDomain]=useState('all'),[q,setQ]=useState('');useEffect(()=>{api<SemanticObject[]>('/objects').then(setObjects)},[]);const visible=objects.filter(o=>(domain==='all'||o.metadata.domain===domain)&&JSON.stringify(o.metadata).toLowerCase().includes(q.toLowerCase()));const nodes:Node[]=visible.map((o,i)=>({id:objectId(o),position:{x:(i%3)*340,y:Math.floor(i/3)*250},data:{label:<div className="graph-node"><header><span className="domain-chip">{o.metadata.domain}</span><Verified value={isVerified(o.metadata)}/></header><strong>{o.metadata.label||o.metadata.name}</strong><code>{o.metadata.name}</code><div>{o.spec.dimensions.slice(0,4).map(d=><span key={d.name}><code>{d.name}</code><small>{d.type}</small></span>)}</div></div>}}));const edges:Edge[]=visible.flatMap(o=>o.spec.relationships.filter(r=>visible.some(v=>objectId(v)===r.targetObject)).map(r=>({id:objectId(o)+'-'+r.name,source:objectId(o),target:r.targetObject,label:r.cardinality.replaceAll('_',' : '),animated:o.metadata.domain!==visible.find(v=>objectId(v)===r.targetObject)?.metadata.domain,markerEnd:{type:MarkerType.ArrowClosed,color:'#4a45c4'},style:{stroke:'#4a45c4'},labelStyle:{fontFamily:'JetBrains Mono',fontSize:9,fill:'#5c5f66'}})));return <><PageHeader eyebrow="Model topology" title="Entity relationships" description="Explore declared joins and cross-domain paths."/><section className="diagram-toolbar"><div className="search-field"><Icon name="search" size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Find an object"/></div><select value={domain} onChange={e=>setDomain(e.target.value)}><option value="all">All domains</option>{[...new Set(objects.map(o=>o.metadata.domain))].map(d=><option key={d}>{d}</option>)}</select><span>{visible.length} nodes · {edges.length} relationships</span></section><div className="flow"><ReactFlow nodes={nodes} edges={edges} fitView onNodeDoubleClick={(_,node)=>navigate('/objects/'+node.id)}><Background color="#d9dae0" gap={22}/><MiniMap nodeColor="#4a45c4" maskColor="#f2f2f4cc"/><Controls/></ReactFlow></div><section className="panel relationship-fallback"><PanelTitle title="Relationship list"/>{visible.flatMap(o=>o.spec.relationships.map(r=><div key={objectId(o)+r.name}><Link to={'/objects/'+objectId(o)}>{o.metadata.domain}.{o.metadata.name}</Link><span>{r.cardinality.replaceAll('_',' ')}</span><Link to={'/objects/'+r.targetObject}>{r.targetObject}</Link></div>))}</section></>}

function NotFound(){return <Empty title="Page not found" body="The requested semantic model page does not exist." action={<Link className="button primary" to="/">Back to catalog</Link>}/>}
